INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('센소지', '浅草寺', 'SHRINE_TEMPLE', '東京都', '台東区', 35.714765, 139.796655, 'ALWAYS', NULL, NULL, NULL, '경내 24시간. 본당 6:00~17:00 (10~3월은 6:30부터)', '무료', '도쿄에서 가장 오래된 절. 커다란 붉은 등이 걸린 가미나리몬과 기념품 가게가 늘어선 나카미세 거리를 지나 본당에 닿는다.', '본당이 닫힌 뒤에도 경내 라이트업이 밤 11시쯤까지 이어져 야경 산책이 좋다.', NULL, 'https://www.senso-ji.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도쿄 스카이트리', '東京スカイツリー', 'VIEWPOINT', '東京都', '墨田区', 35.710063, 139.810700, 'FIXED', '10:00', '22:00', NULL, '토·일·공휴일은 9:00부터. 최종 입장 21:00', '날짜별 요금 (공식 사이트 확인)', '높이 634m, 일본에서 가장 높은 전파탑. 350m 덴보 데크와 450m 덴보 회랑에서 도쿄 전체가 내려다보인다.', '요금이 날짜·시간대마다 달라서 공식 사이트에서 미리 확인하고 웹 예매하는 편이 싸다.', NULL, 'https://www.tokyo-skytree.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('우에노 동물원', '恩賜上野動物園', 'AMUSEMENT', '東京都', '台東区', 35.716327, 139.771328, 'FIXED', '09:30', '17:00', 'MON', '입장은 16:00까지. 월요일이 공휴일이면 다음 날 휴원', '600엔', '1882년에 문을 연 일본 최초의 동물원. 우에노 공원 안에 있어 박물관·미술관과 묶어 돌기 좋다.', '동원과 서원이 꽤 떨어져 있어 모노레일 대신 이케노하타 쪽 길로 걷는 게 편하다.', NULL, 'https://www.tokyo-zoo.net/zoo/ueno/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('우에노 온시 공원', '上野恩賜公園', 'PARK_GARDEN', '東京都', '台東区', 35.714930, 139.773660, 'FIXED', '05:00', '23:00', NULL, '시간 외 출입 금지. 안의 박물관·동물원은 시간 별도', '무료', '1873년 일본 최초로 지정된 공원 중 하나. 벚꽃 약 800그루와 국립박물관·미술관, 연꽃이 피는 시노바즈 연못이 한데 모여 있다.', '시노바즈 연못 가운데 팔각형 벤텐도까지 걸어 들어갈 수 있고, 연못에서 오리배도 탈 수 있다.', NULL, 'https://www.kensetsu.metro.tokyo.lg.jp/jimusho/toubuk/ueno/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('신주쿠 교엔', '新宿御苑', 'PARK_GARDEN', '東京都', '新宿区', 35.685175, 139.710052, 'FIXED', '09:00', '16:30', 'MON', '폐원은 10/1~3/14 16:30, 3/15~6/30·8/21~9/30 18:00, 7/1~8/20 19:00. 월요일이 공휴일이면 다음 평일 휴원, 3/25~4/24·11/1~11/15는 무휴, 12/29~1/3 휴원', NULL, '일본식·영국식·프랑스식 정원이 한곳에 모인 국민 정원. 도심 한복판인데도 잔디밭이 넓어 피크닉하기 좋다.', '벚꽃 시즌에는 입구 줄이 길어서 신주쿠몬보다 오키도몬·센다가야몬이 빨리 들어간다.', NULL, 'https://fng.or.jp/shinjuku/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도쿄 타워', '東京タワー', 'VIEWPOINT', '東京都', '港区', 35.658581, 139.745433, 'FIXED', '09:00', '23:00', NULL, '최종 입장 22:30', '메인 덱 1,500엔', '1958년에 세운 높이 333m의 붉은 전파탑. 150m 메인 덱과 250m 톱 덱에서 도심 야경을 본다.', '바로 아래 시바 공원 쪽에서 올려다보는 타워 사진이 예쁘다.', NULL, 'https://www.tokyotower.co.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('메이지 신궁', '明治神宮', 'SHRINE_TEMPLE', '東京都', '渋谷区', 35.676398, 139.699326, 'VARIES', NULL, NULL, NULL, '해 뜰 때 열고 해 질 때 닫아 달마다 다름 (예: 11월 6:10~16:10, 12월 6:40~16:00)', '무료 (신궁 교엔은 유료)', '메이지 천황과 쇼켄 황태후를 모신 신사. 하라주쿠역 바로 옆인데도 70만㎡ 숲에 들어서면 도시 소리가 사라진다.', '경내 메이지 신궁 교엔(유료)의 기요마사 우물은 6월 꽃창포 철에 특히 붐빈다.', NULL, 'https://www.meijijingu.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('고쿄 히가시교엔', '皇居東御苑', 'PARK_GARDEN', '東京都', '千代田区', 35.685500, 139.755300, 'FIXED', '09:00', '16:00', 'MON,FRI', '폐원은 11/1~2월말 16:00, 10월 16:30, 3/1~4/14·9월 17:00, 4/15~8/31 18:00. 공휴일이면 개원, 12/28~1/3 휴원', '무료', '옛 에도성 혼마루 자리를 정원으로 꾸며 일반에 공개한 곳. 천수대 돌담과 계절 꽃을 무료로 볼 수 있다.', '오테몬으로 들어가 천수대에 오르면 에도성 규모가 실감 난다.', NULL, 'https://www.kunaicho.go.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('하마리큐 온시 정원', '浜離宮恩賜庭園', 'PARK_GARDEN', '東京都', '中央区', 35.659970, 139.763390, 'FIXED', '09:00', '17:00', NULL, '입장 16:30까지. 12/29~1/1 휴원', NULL, '바닷물을 끌어들인 연못이 있는 옛 쇼군가 정원. 고층 빌딩을 배경으로 연못 위 찻집에서 말차를 마실 수 있다.', '봄 유채꽃과 가을 코스모스 철이 특히 예쁘다.', NULL, 'https://www.tokyo-park.or.jp/teien/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('리쿠기엔', '六義園', 'PARK_GARDEN', '東京都', '文京区', 35.733260, 139.746560, 'FIXED', '09:00', '17:00', NULL, '입장 16:30까지. 12/29~1/1 휴원', '300엔', '에도 시대를 대표하는 회유식 다이묘 정원. 와카에 나오는 풍경 88곳을 정원 안에 재현했다.', '봄 수양벚꽃과 가을 단풍 철에는 야간 라이트업을 한다.', NULL, 'https://www.tokyo-park.or.jp/teien/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('고이시카와 고라쿠엔', '小石川後楽園', 'PARK_GARDEN', '東京都', '文京区', 35.705730, 139.749480, 'FIXED', '09:00', '17:00', NULL, '입장 16:30까지. 12/29~1/1 휴원', '300엔', '미토 도쿠가와 가문이 만든 도쿄에서 가장 오래된 다이묘 정원. 둥근 엔게쓰쿄 다리가 물에 비쳐 보름달처럼 보인다.', '도쿄 돔 바로 옆이라 야구 관람 전에 들르기 좋다.', NULL, 'https://www.tokyo-park.or.jp/teien/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('시부야 스카이', 'SHIBUYA SKY', 'VIEWPOINT', '東京都', '渋谷区', 35.658450, 139.702200, 'FIXED', '10:00', '22:30', NULL, '최종 입장 21:20. 1월 1일 휴관. 강풍·비 등 날씨에 따라 옥상 폐쇄', '웹 2,700엔부터 (15시 이후 인상)', '시부야 스크램블 스퀘어 꼭대기 229m 옥상 전망대. 발아래 스크램블 교차로와 도쿄 야경이 탁 트여 보인다.', '옥상엔 모자·삼각대 반입 금지라 46층 로커에 맡긴다. 일몰 시간대 표는 빨리 매진된다.', NULL, 'https://www.shibuya-scramble-square.com/sky/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('도쿄도청 전망실', '東京都庁展望室', 'VIEWPOINT', '東京都', '新宿区', 35.689630, 139.692100, 'FIXED', '09:30', '22:00', NULL, '입실 21:30까지. 남·북 전망실이 정기 점검일에 번갈아 쉼, 연말연시 휴실', '무료', '도청 제1본청사 45층, 지상 202m의 무료 전망실. 날씨가 맑으면 후지산까지 보인다.', '해가 지면 청사 외벽 프로젝션 매핑도 무료로 볼 수 있다.', NULL, 'https://www.yokoso.metro.tokyo.lg.jp/tenbou/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('네즈 신사', '根津神社', 'SHRINE_TEMPLE', '東京都', '文京区', 35.720160, 139.760900, 'VARIES', NULL, NULL, NULL, '여름 5:00~18:00, 겨울 6:00~17:00 (바뀌는 날짜는 공개 안 됨)', '무료', '닛코 도쇼구 양식을 이어받은 중요문화재 신사. 오토메 이나리로 이어지는 붉은 도리이 길이 사진 명소다.', '4월 쓰쓰지 축제 때는 100종이 넘는 철쭉이 언덕을 덮는다.', NULL, 'https://www.nedujinja.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('간다 묘진', '神田明神', 'SHRINE_TEMPLE', '東京都', '千代田区', 35.701950, 139.767960, 'ALWAYS', NULL, NULL, NULL, '경내 상시 개방', '경내 무료, 자료관 500엔', '730년 창건, 에도의 총진수로 섬겨진 신사. 아키하바라와 가까워 애니메이션 콜라보 부적으로도 유명하다.', '2년에 한 번 5월 중순에 에도 3대 마쓰리인 간다 마쓰리가 열린다.', NULL, 'https://www.kandamyoujin.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('시바마타 다이샤쿠텐', '柴又帝釈天（題経寺）', 'SHRINE_TEMPLE', '東京都', '葛飾区', 35.758320, 139.877900, 'FIXED', '05:00', '20:00', NULL, '조각 갤러리·스이케이엔 정원은 9:00~16:00 (유료)', '경내 무료, 조각 갤러리·정원 유료', '영화 「남자는 괴로워」의 무대인 절. 제석당 외벽을 빈틈없이 덮은 법화경 설화 조각 때문에 "조각의 절"이라 불린다.', '역에서 절까지 200m 참배길에서 쑥떡 구사당고를 먹으며 걸어가자.', NULL, 'https://www.taishakuten.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('야나카 긴자', '谷中銀座商店街', 'HISTORIC', '東京都', '台東区', 35.727700, 139.765400, 'ALWAYS', NULL, NULL, NULL, '거리는 상시. 가게마다 영업시간·휴일이 다름', '무료', '쇼와 시대 분위기가 남은 짧은 상점가. 고로케·멘치카쓰 같은 길거리 음식을 먹으며 걷기 좋다.', '계단 위 "유야케 단단"에서 보는 해 질 녘 상점가가 명물.', NULL, 'https://www.yanakaginza.com/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('지치부 신사', '秩父神社', 'SHRINE_TEMPLE', '埼玉県', '秩父市', 35.997700, 139.084900, 'VARIES', NULL, NULL, NULL, '신문 5:00~20:00, 겨울은 6:00부터 (바뀌는 날짜는 공개 안 됨)', '무료', '2100년 역사를 가진 지치부의 총진수. 도쿠가와 이에야스가 기진한 본전에 히다리 진고로 작으로 전해지는 "쓰나기의 용" 조각이 있다.', '12월 2~3일 지치부 요마쓰리 때는 이 신사를 중심으로 화려한 수레와 불꽃이 펼쳐진다.', NULL, 'https://www.chichibu-jinja.or.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('히쓰지야마 공원', '羊山公園', 'PARK_GARDEN', '埼玉県', '秩父市', 35.985700, 139.092900, 'ALWAYS', NULL, NULL, NULL, '공원은 상시 개방. 시바자쿠라 언덕은 개화기(4월 중순~5월 초)에만 8:00~17:00 유료', '무료 (시바자쿠라 개화기 언덕 300엔)', '부코산을 배경으로 40만 그루 넘는 꽃잔디가 언덕을 덮는 지치부의 봄 명소. 양 목장과 벚꽃 길도 있다.', '세이부치치부역에서 걸어서 20분쯤. 꽃잔디는 언덕 위에서 내려다볼 때 무늬가 잘 보인다.', NULL, 'https://navi.city.chichibu.lg.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('사와라 오노가와 거리', '佐原 小野川沿いの町並み', 'HISTORIC', '千葉県', '香取市', 35.889000, 140.499500, 'ALWAYS', NULL, NULL, NULL, '거리는 상시. 가게·시설은 각자 영업시간', '무료', '"북총의 작은 에도"라 불리는 수향 마을. 오노가와 운하를 따라 에도 시대 상가와 창고가 줄지어 있는 중요전통적건조물군 보존지구다.', '작은 배를 타고 운하를 도는 오노가와 뱃놀이가 인기.', NULL, 'https://www.city.katori.lg.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이노 다다타카 기념관', '伊能忠敬記念館', 'HISTORIC', '千葉県', '香取市', 35.889600, 140.499300, 'FIXED', '09:00', '16:30', 'MON', '월요일이 공휴일이면 다음 평일 휴관. 12/29~1/1 휴관', '500엔', '55세에 전국 측량을 시작해 일본 최초의 실측 지도를 만든 이노 다다타카의 기념관. 국보 이노 지도와 측량 도구를 전시한다.', '건너편 이노 다다타카 옛집(무료)과 함께 보면 30분~1시간이면 충분하다.', NULL, 'https://www.city.katori.lg.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('이노 다다타카 옛집', '伊能忠敬旧宅', 'HISTORIC', '千葉県', '香取市', 35.889300, 140.499000, 'FIXED', '09:00', '16:30', NULL, '12/29~1/1 휴관', '무료', '이노 다다타카가 30여 년을 산 상가 건물. 오노가와 운하에 면한 가게 자리와 안채가 그대로 남아 있다.', '운하 건너편 이노 다다타카 기념관과 함께 보자.', NULL, 'https://www.city.katori.lg.jp/', DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('가토리 신궁', '香取神宮', 'SHRINE_TEMPLE', '千葉県', '香取市', 35.886300, 140.533800, 'ALWAYS', NULL, NULL, NULL, '경내 참배 자유. 授与所·고슈인 8:30~17:00', '경내 무료, 보물관 300엔', '간토에서 손꼽히는 격식의 고사. 깊은 숲속에 붉은 누문과 중요문화재 본전이 서 있다.', '사와라 거리에서 차로 10분쯤이라 같은 날 묶어 돌기 좋다.', NULL, 'https://katori-jingu.or.jp/', DATE '2026-11-22', NULL);
